95	<body>
96	
97	<h1>Swizzle Layout — SWIZZLE_128B</h1>
98	<div class="sub">physical_sector = logical_sector XOR row &nbsp;|&nbsp; 8 rows &times; 32 banks, 4 banks per sector</div>
99	
100	<div class="controls">
101	  <div><span class="lbl">Read</span>
102	    <div class="bg" id="rt">
103	      <button class="btn on" data-v="col">Column Tile (8&times;4)</button>
104	      <button class="btn" data-v="row">Row Tile (1&times;32)</button>
105	    </div>
106	  </div>
107	  <div><span class="lbl">Index</span><div class="bg" id="ri"></div></div>
108	</div>
109	
110	<div class="panels">
111	  <svg class="arrow-svg" id="arrow"></svg>
112	  <div class="panel"><h2>Without Swizzle</h2>
113	    <div class="grid" id="g0"></div>
114	    <div class="blab">32 Banks</div>
115	    <div class="bbar" id="bk0"></div>
116	    <div class="st" id="s0"></div>
117	  </div>
118	  <div class="panel"><h2>SWIZZLE_128B</h2>
119	    <div class="grid" id="g1"></div>
120	    <div class="blab">32 Banks</div>
121	    <div class="bbar" id="bk1"></div>
122	    <div class="st" id="s1"></div>
123	  </div>
124	</div>
125	<div class="leg" id="lg"></div>
126	
127	<div class="tl-wrap">
128	  <div class="tl-head">Cycle-by-Cycle Reads</div>
129	  <div class="cbar" id="cbar"></div>
130	  <div class="tl-grid">
131	    <div class="tl-box"><h3>Without Swizzle</h3><div id="tl0"></div><div class="tl-sum" id="ts0"></div></div>
132	    <div class="tl-box"><h3>SWIZZLE_128B</h3><div id="tl1"></div><div class="tl-sum" id="ts1"></div></div>
133	  </div>
134	</div>
135	
136	<div class="info">
137	  1 element = 1 bank (4 bytes). A warp of 32 threads reads 32 elements; bank conflicts serialize into extra cycles.<br>
138	  <b>Column Tile (8&times;4)</b>: 8 rows &times; 4 cols (1 sector) = 32 reads.
139	  With swizzle: <b>1 cycle</b>. Without: <b>8 cycles</b> (8-way conflicts).<br>
140	  <b>Row Tile (1&times;32)</b>: 1 row &times; 32 cols = 32 reads.
141	  Always <b>1 cycle</b> (all 32 banks distinct within a row).
142	</div>
143	
144	<script>
145	// 32 bank colors: 4 shades per sector
146	const SEC_BASE=['#5b9bd5','#ed9a3c','#d95555','#45b5a5','#5fb85f','#e0b828','#9d6eb5','#e87888'];
147	function hexToHSL(hex){
148	  let r=parseInt(hex.slice(1,3),16)/255,g=parseInt(hex.slice(3,5),16)/255,b=parseInt(hex.slice(5,7),16)/255;
149	  const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;
150	  let h=0,s=0,l=(mx+mn)/2;
151	  if(d>0){s=d/(1-Math.abs(2*l-1));h=mx===r?((g-b)/d+6)%6:mx===g?(b-r)/d+2:(r-g)/d+4;h*=60;}
152	  return[h,s*100,l*100];
153	}
154	function hslToHex(h,s,l){
155	  s/=100;l/=100;
156	  const a=s*Math.min(l,1-l);
157	  const f=n=>{const k=(n+h/30)%12;return Math.round(255*(l-a*Math.max(Math.min(k-3,9-k,1),-1)));};
158	  return'#'+[f(0),f(8),f(4)].map(x=>x.toString(16).padStart(2,'0')).join('');
159	}
160	const BK=[];
161	for(let s=0;s<8;s++){
162	  const[h,sat,lit]=hexToHSL(SEC_BASE[s]);
163	  for(let i=0;i<4;i++){
164	    const lOff=(i-1.5)*6;
165	    BK.push(hslToHex(h,sat,Math.max(20,Math.min(80,lit+lOff))));
166	  }
167	}
168	
169	const ROWS=8,SECS=8,BPS=4,BCOLS=32;
170	const ST={t:'col',i:-1,c:0,pl:false,tm:null};
171	
172	const swizSec=(row,sec)=>sec^row;
173	function physBank(row,bc,sw){
174	  const sec=Math.floor(bc/BPS),off=bc%BPS;
175	  return(sw?swizSec(row,sec):sec)*BPS+off;
176	}
177	function logAtPhys(row,p,sw){
178	  const ps=Math.floor(p/BPS),off=p%BPS;
179	  return(sw?swizSec(row,ps):ps)*BPS+off;
180	}
181	
182	function getCells(){
183	  if(ST.i<0)return[];
184	  if(ST.t==='col'){
185	    // Col tile: 8 rows × 4 columns (1 sector)
186	    const cl=[];const s0=ST.i*BPS;
187	    for(let off=0;off<BPS;off++) for(let r=0;r<ROWS;r++) cl.push({r,bc:s0+off});
188	    return cl;
189	  }
